"""Static file server with CORS headers, for the Perfetto launcher page (open.html) and FISH HTML pages.
  python3 serve_cors.py <directory> [port=8791]     binds 127.0.0.1 only."""
import http.server, os, sys, functools
d = sys.argv[1]; port = int(sys.argv[2]) if len(sys.argv) > 2 else 8791
class H(http.server.SimpleHTTPRequestHandler):
    def end_headers(self):
        self.send_header('Access-Control-Allow-Origin', '*'); self.send_header('Cache-Control', 'no-store')
        super().end_headers()
    def log_message(self, *a): pass
http.server.ThreadingHTTPServer(('127.0.0.1', port), functools.partial(H, directory=os.path.abspath(d))).serve_forever()
